using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new() { Name = "MyMcpServer", Version = "1.0.0" };
    })
    .WithTools<MyTools>()
    .WithResources<MyResources>()
    .WithHttpTransport();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class MyTools
{
    [McpServerTool(Name = "echo", Title = "Echo Tool")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "add", Title = "Add Numbers")]
    public static string Add(double a, double b) => $"Result: {a + b}";
}

[McpServerResourceType]
public static class MyResources
{
    [McpServerResource(UriTemplate = "config://app", Name = "app-config",
        Title = "Application Configuration", MimeType = "application/json")]
    public static string GetAppConfig()
    {
        return """
        {
            "environment": "production",
            "version": "1.0.0",
            "features": {
                "darkMode": true,
                "maxItems": 100
            }
        }
        """;
    }

    [McpServerResource(UriTemplate = "config://endpoints", Name = "endpoints",
        Title = "API Endpoints", MimeType = "application/json")]
    public static string GetEndpoints()
    {
        return """
        {
            "api": "https://api.example.com/v1",
            "auth": "https://auth.example.com",
            "docs": "https://docs.example.com"
        }
        """;
    }
}

